insert into public.minigame_instances (key, locale, instruction, tasks, target, variant, success, minigame_id, params, source_path, source_metadata) select key, locale, instruction, tasks, target, variant, success, minigame_id, params, source_path, source_metadata from jsonb_to_recordset($seed$[]$seed$::jsonb) as entries(key text, locale text, instruction text, tasks jsonb, target text, variant text, success text, minigame_id text, params jsonb, source_path text, source_metadata jsonb) on conflict (key, locale) do update set instruction = excluded.instruction, tasks = excluded.tasks, target = excluded.target, variant = excluded.variant, success = excluded.success, minigame_id = excluded.minigame_id, params = excluded.params, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
